-- 기관 상세 — 서울시 목록의 상세 페이지에서 옮겨 적는다.
--
-- V4 는 목록 페이지만 읽고 이메일·전화번호를 일부러 두고 왔다 ("화면이 쓰지 않는 데다,
-- 받아 두면 지킬 것만 늘어난다"). 화면이 이제 그것을 쓴다 — 기관을 눌러 들어간 사람이
-- 바로 다음에 하려는 일이 연락이기 때문이다. 그래서 상세 페이지를 다시 읽었다.
-- 받은 날: 2026-08-19 · 받은 스크립트: app/scrape-detail.mjs · 100곳 전부 성공.
--
-- **여기 있는 값은 전부 기관이 서울시에 제출한 것이고, 협회가 확인한 것이 아니다.**
-- 협회가 확인한 것은 배지 옆 두 줄뿐이다(28장). 화면도 이 묶음을 '서울시 목록에서
-- 옮겨 적음'이라고 먼저 밝히고 보여 준다 — 밝히지 않으면 협회가 진료 시간과 병상 수까지
-- 확인해 준 것처럼 읽힌다.
--
-- 7장은 기관이 자기 정보를 직접 관리한다고 정했다. 그 길이 열리면 이 칸들은 기관이
-- 고치는 값이 되고, 이 파일은 그때까지의 초기값이다 (V8 의 사진과 같은 처지).
--
-- 사진은 가져오지 않았다. 상세 페이지에는 기관마다 1~12장이 base64 로 박혀 있는데,
-- 100곳어치를 받으면 저장소가 사진으로 불어나고 사진은 원래 기관이 올릴 것이다(7장).

ALTER TABLE medicheck_listing ADD COLUMN transport      TEXT;
ALTER TABLE medicheck_listing ADD COLUMN features       TEXT;
ALTER TABLE medicheck_listing ADD COLUMN hours          TEXT;
ALTER TABLE medicheck_listing ADD COLUMN phone          TEXT;
ALTER TABLE medicheck_listing ADD COLUMN email          TEXT;
ALTER TABLE medicheck_listing ADD COLUMN address_detail TEXT;
ALTER TABLE medicheck_listing ADD COLUMN doctors        INTEGER;
ALTER TABLE medicheck_listing ADD COLUMN beds           INTEGER;
-- 상세 페이지를 읽은 날. verified_at(협회가 목록에서 그 기관을 확인한 날)과 다른 날이고
-- 뜻도 다르므로 칸을 따로 둔다 — 한 칸에 섞으면 화면이 둘을 같은 것으로 말하게 된다.
ALTER TABLE medicheck_listing ADD COLUMN detail_read_at TEXT;

